SET NOCOUNT ON; SET XACT_ABORT ON; IF DB_NAME() NOT LIKE N'OptionCIsolated[_]%' THROW 52010,N'CANDIDATE_DISPOSABLE_TARGET_REQUIRED',1; IF (SELECT TOP(1) VersionNumber FROM dbo.SchemaVersions ORDER BY AppliedAt DESC,VersionNumber DESC)<>N'1.8.0-014' THROW 52011,N'BACKFILL_REQUIRES_014',1; IF EXISTS(SELECT 1 FROM dbo.LocationPublishedVersions WHERE VersionNumber=1) THROW 52012,N'VERSION_1_BACKFILL_ALREADY_DONE',1; INSERT dbo.LocationPublishedVersions(LocationId,VersionNumber,ChangeRequestId,IsCurrent,PublishedJson,PublishedAt) SELECT LocationId,1,NULL,1,N'{}',SYSUTCDATETIME() FROM dbo.Locations WHERE IsActive=1 AND ApprovalStatus=N'Approved'; SELECT N'BACKFILL_OK' Result;